-- composition of rule kernels OmitOrderBy x SimplifyJoin (sqlite), template graft_exists
SELECT a1.c0 AS c0, CAST(0.5 AS REAL) AS c1, a2.c0 AS c2, '1970-01-01' AS c3 FROM (tp AS a1 FULL JOIN (SELECT * FROM t4 WHERE EXISTS (SELECT 1 FROM (SELECT FALSE AS c0, '{}' AS c1 FROM (SELECT '2024-12-31' AS c0, CAST('ß' AS TEXT) AS c1, 100 AS c2 FROM t2 AS a1 ORDER BY 2) AS a2 ORDER BY 2) AS kb) OR NOT EXISTS (SELECT 1 FROM (SELECT FALSE AS c0, '{}' AS c1 FROM (SELECT '2024-12-31' AS c0, CAST('ß' AS TEXT) AS c1, 100 AS c2 FROM t2 AS a1 ORDER BY 2) AS a2 ORDER BY 2) AS kb)) AS a2 ON (a1.c0 = a2.c1)) WHERE (a2.c0 > 100);
